import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { callCoreBridgeAction, CORE_BRIDGE_ACTIONS, CORE_BRIDGE_URL } from './core-bridge.mjs';

// Signed F12.3 production contract probe, intentionally NEVER valid for
// acquire/resume. A rejected foreign account is checked in the Bridge's
// payload validator, before the Core/RPC. Stage/ACK use the NIL UUID, which
// cannot be generated by gen_random_uuid() and is never a valid lease.
// No imports of production writers or Shopee transport.
const ACCOUNT='b4027369-5abf-4ac1-ab24-862334fae892';
const DENIED_ACCOUNT='00000000-0000-4000-8000-000000000001';
const NIL_LEASE='00000000-0000-0000-0000-000000000000';
const cases=Object.freeze([
  {name:'acquire_foreign_account',action:CORE_BRIDGE_ACTIONS.F12_ADAO_ACQUIRE,
    data:{channel_account_id:DENIED_ACCOUNT},status:400,error:'invalid_request'},
  {name:'resume_foreign_account',action:CORE_BRIDGE_ACTIONS.F12_ADAO_RESUME,
    data:{channel_account_id:DENIED_ACCOUNT},status:400,error:'invalid_request'},
  {name:'stage_invalid_lease',action:CORE_BRIDGE_ACTIONS.F12_ADAO_STAGE,
    data:{channel_account_id:ACCOUNT,lease_id:NIL_LEASE,generation:1,
      checkpoint:null,pages:[['26111200000001']],completed:true},
    status:409,code:'stale_lease'},
  {name:'ack_invalid_lease',action:CORE_BRIDGE_ACTIONS.F12_ADAO_ACK,
    data:{channel_account_id:ACCOUNT,lease_id:NIL_LEASE,generation:1},
    status:409,code:'stale_or_staged_requires_reconciliation'},
]);

export async function runF12NonmutatingRpcContractProbe({
  secret=process.env.CORE_BRIDGE_HMAC_SECRET,
  fetchImpl=globalThis.fetch,
  call=callCoreBridgeAction,
}={}){
  if(typeof secret!=='string'||secret.length<1)
    return {ok:false,code:'hmac_secret_unavailable',checks:[]};
  if(typeof fetchImpl!=='function'||typeof call!=='function')
    return {ok:false,code:'transport_unavailable',checks:[]};
  const checks=[];
  for(const entry of cases){
    let response;
    try{
      response=await call({
        action:entry.action,data:entry.data,
        url:CORE_BRIDGE_URL,secret,fetchImpl,
        logger:()=>{},timeoutMs:5000,
      });
    }catch{
      return {ok:false,code:'transport_unavailable',checks};
    }
    const valid=response?.status===entry.status
      && response?.payload?.[entry.code?'code':'error']===(entry.code??entry.error)
      && (entry.status===400 || (
        typeof response?.payload?.request_id==='string'
        && response.payload.request_id===response.requestId));
    checks.push({name:entry.name,ok:valid,status:response?.status??null});
    // Stop on unexpected response: never escalate to additional probes.
    if(!valid)return {ok:false,code:'contract_mismatch',checks};
  }
  return {ok:true,code:'f12_rejections_verified',checks,
    warning:'acquire/resume account rejection alone does not prove positive runtime dispatch'};
}

if(process.argv[1]&&pathToFileURL(resolve(process.argv[1])).href===import.meta.url){
  if(process.argv.length!==3||process.argv[2]!=='--live-nonmutating-contract'){
    console.error('Usage: node f12-3-core-bridge-nonmutating-contract.mjs --live-nonmutating-contract');
    process.exitCode=2;
  }else{
    const result=await runF12NonmutatingRpcContractProbe();
    console.log(JSON.stringify(result));
    if(!result.ok)process.exitCode=1;
  }
}
